from __future__ import annotations

import ast
import re
import tokenize
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PACKAGE = ROOT / "twinrl_onco"
TESTS = ROOT / "checkrides"

FORBIDDEN = [
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "skeleton",
    "placeholder",
    "todo from paper",
    "cutting-edge",
    "seamlessly",
    "leveraging",
    "utilize",
    "delve",
    "holistic",
    "meticulously",
    "it's worth noting",
    "in conclusion",
]

EMOJI = re.compile("[\U0001f000-\U0001faff\U00002600-\U000027bf\U0001f1e6-\U0001f1ff⬀-⯿←-⇿⌀-⏿]")


SELF = Path(__file__).resolve()


def _python_files() -> list[Path]:
    files = sorted(PACKAGE.rglob("*.py")) + sorted(TESTS.rglob("*.py"))
    return [p for p in files if p.resolve() != SELF]


def _text_files() -> list[Path]:
    extra = [ROOT / "README.md", ROOT / "Makefile"]
    return [p for p in extra if p.exists()]


def test_no_comments_in_python():
    for path in _python_files():
        with path.open("rb") as handle:
            for tok in tokenize.tokenize(handle.readline):
                assert tok.type != tokenize.COMMENT, f"comment in {path}"


def test_no_docstrings_in_python():
    for path in _python_files():
        tree = ast.parse(path.read_text())
        for node in ast.walk(tree):
            if isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                doc = ast.get_docstring(node)
                assert doc is None, f"docstring in {path}"


def test_no_forbidden_phrases():
    for path in _python_files() + _text_files():
        lowered = path.read_text().lower()
        for phrase in FORBIDDEN:
            assert phrase not in lowered, f"forbidden phrase {phrase!r} in {path}"


def test_no_emoji():
    for path in _python_files() + _text_files():
        assert EMOJI.search(path.read_text()) is None, f"emoji in {path}"
